W=[
E('hospital','英 /ˈhɒspɪtəl/；美 /ˈhɑːspɪtəl/','医院；慈善收容机构〔历史用法〕','最初是让需要帮助的人住下、得到照料的地方，后来“照料病人”成为最熟悉的用途。','拉丁 hospes / hospit- 客人与主人 → hospitalis 与待客有关 → hospitale 接待处；经古法语 hospital 进入英语。不是 host 加一个现代英语 -pital。',HOSP,'现代主要指提供诊疗和住院等服务的医院。英国英语 be in hospital 常指住院，美国英语通常说 be in the hospital。历史机构名字里的 Hospital 有时保留慈善养育、收容义。','a children’s hospital；be admitted to hospital；hospital care。','clinic 往往指门诊或专门诊所；hospital 常可提供住院照护，但实际机构名称和规模各有不同。',('She visited her father in hospital after work.','下班后，她去医院看望住院的父亲。'),('The hospital opened a new outpatient department.','这家医院开设了新的门诊部。'),sources=['https://en.wiktionary.org/wiki/hospital','https://www.etymonline.com/word/hospital']),
E('hotel','英 /həʊˈtel/；美 /hoʊˈtel/','旅馆；酒店','为付费客人安排住宿和相关服务的地方，核心仍是把来客安顿下来。','借法语 hôtel，接较早 hostel / ostel，远源同 hospitale。是和 hospital、hostel 不同时间、不同形式的借入，不是英语把 hospital 中间删掉才造出 hotel。',HOTEL,'常见 check into a hotel、book a hotel room。法语 hôtel 的历史范围还包括大宅和公共建筑，因此看到法国 Hôtel de Ville 不能照英语把它当酒店；它是市政厅。','a hotel room；stay at a hotel；a hotel reservation。','hotel 通常按客房提供商业住宿；hostel 常有共享寝室和设施，但并非所有 hostel 都只有多人房。',('We booked a hotel near the station.','我们订了一家车站附近的酒店。'),('The hotel offers breakfast in a small courtyard.','这家酒店在一个小庭院里供应早餐。')),
E('host','英 /həʊst/；美 /hoʊst/','主人；主持人；主办；宿主；主机；大量〔另一路〕；圣饼〔另一路〕','在最常见的一支里，它负责让别人来到这里、在这里活动或得到承载：主人接待客人，主持人组织节目，宿主容纳另一生物。','主人义经古法语 oste / hoste 接拉丁 hospitem；a host of 的“大量”另经法语军队词 ost 接 hostis；宗教“圣饼”另接 hostia。三条借入路线需分开，不能把大量解释成主人很多。',[['主人支：拉丁 hospes / hospitem → 古法语 oste / hoste → 英语 host','接待者；后来扩展到主持人、宿主、主机及动词'],['大量支：拉丁 hostis → 古法语 ost / host → 英语 host','敌方、军队 → 队伍、大群'],['圣饼支：拉丁 hostia → 古法语 hoiste 等 → 英语 host','祭品 → 基督教圣餐中的圣饼']], 'host a meeting 是主办或主持会议。生物宿主不表示主动欢迎寄生者；网络 host 则说联网的主机，也可用作动词说提供网站运行环境。a host of problems 单独走“大量”这条路。','the host of a show；host an event；a host organism；a host of reasons。','guest 是来客，host 是接待方；但 host 的所有义项并非都由 guest 的对面推出来。',('Our host made sure everyone had a place to sit.','主人确保每个人都有座位。'),('The city will host the music festival.','这座城市将举办音乐节。'),('The change created a host of new problems.','这一变化带来了一大堆新问题。'),sources=['https://www.etymonline.com/word/host','https://en.wiktionary.org/wiki/host']),
E('hospitality','英 /ˌhɒspɪˈtæləti/；美 /ˌhɑːspɪˈtæləti/','好客；款待；酒店餐饮接待业','让来的人感到被欢迎、被安顿：给一杯热茶、安排住处、照顾需要，都能体现 hospitality。','拉丁 hospitalitas 接 hospitalis，经法语 hospitalité 借入。不是现代 hospital“医院”加 -ity 才变成好客；它和医院名词共享更早的待客词干。',HOSPITALITY,'thank someone for their hospitality 是感谢款待。the hospitality industry 则是商业语境，涵盖酒店、餐饮及相关接待服务，不是医院行业。','warm hospitality；thank you for your hospitality；the hospitality industry。','kindness 泛指善意；hospitality 特别落实在欢迎、接待和照料来客。',('Thank you for your generous hospitality during our visit.','谢谢你在我们到访期间的热情款待。'),('She has worked in hospitality for ten years.','她在酒店餐饮服务行业工作了十年。')),
E('hostel','英 /ˈhɒstəl/；美 /ˈhɑːstəl/','青年旅舍；集体住宿处；临时收容住所','把床位和公共设施集中提供给旅人或暂时需要住处的人，常比酒店更突出共享住宿。','中古英语 hostel 借古法语 hostel / ostel，接后期拉丁 hospitale。与较晚借入的 hotel 同源，而不是现代英语 hotel 插入 s。',HAL+[['古法语 hostel / ostel → 中古英语 hostel','住宿处、旅舍'],['英语 hostel','词形后来复兴；现代常指旅舍或集体住宿处']], 'youth hostel 常有多人寝室、共享厨房，也可能有私房。英国的 homeless hostel 可指临时收容住所；部分地区的 student hostel 指学生宿舍。','a youth hostel；a hostel dormitory；stay in a hostel。','hostel 常强调床位或共享设施；hotel 常强调客房和酒店服务。它与 hostile“敌意的”发音、意义不同。',('We stayed in a hostel with a shared kitchen.','我们住在一家有共用厨房的旅舍。'),('The charity runs a hostel for people who need temporary housing.','这家慈善机构经营一处为临时需要住处的人提供住宿的收容所。')),
E('hospice','英 /ˈhɒspɪs/；美 /ˈhɑːspɪs/','临终关怀服务；安宁疗护机构；旅客收容处〔历史用法〕','从让疲惫旅人有地方歇息，走到让生命末期的人得到照护、舒适和陪伴；重点落在减轻痛苦及支持患者与家人。','借法语 hospice，接古法语 hospise / ospice，远源拉丁 hospitium“待客、留宿处”。不由英语 hospital 缩略而来。',H+[['拉丁 hospitium → 古法语 hospise / ospice → 法语 hospice','待客、留宿处；收容照护机构'],['英语 hospice','早期旅人收容处；现代临终关怀服务或机构']], '现代 hospice 既可指机构，也可指服务；hospice care 可以在家里提供。它以舒适、症状缓解和支持为重心，不能理解为完全无人治疗或照料。','hospice care；a hospice nurse；care at home through a hospice。','hospital 是医院的一般词；hospice 特别聚焦生命末期照护。palliative care 的范围更广，并不只限临终阶段。',('The hospice team supported both the patient and her family.','临终关怀团队同时为患者和她的家人提供支持。'),('He received hospice care at home.','他在家中接受临终关怀服务。'),sources=['https://en.wiktionary.org/wiki/hospice','https://www.etymonline.com/word/hospice','https://www.cancer.gov/publications/dictionaries/cancer-terms/def/hospice','https://www.cancer.gov/publications/dictionaries/cancer-terms/def/palliative-care']),
E('hospitable','英 /hɒsˈpɪtəbəl/；美 /hɑːˈspɪtəbəl/，也读 /ˈhɑːspɪtəbəl/','好客的；适宜生存或活动的；乐于接纳的','一个人让来客舒服，一个地方让生命或活动能安顿下来，都可以说 hospitable。','借法语 hospitable；hospit- 接拉丁 hospes / hospitari 的待客词族，-able 是形容词形式。词源资料对中世纪拉丁 hospitabilis 是否作为直接中间形式有不同处理，这里不硬设必经节点。',H+[['拉丁 hospitari / hospit- 词族 → 法语 hospitable','作客、接待相关词干 → 好客的'],['英语 hospitable','热情接待的；引申为条件适合的']], 'hospitable people 热情待客；hospitable to life 说有适宜生命的条件。对新想法也可 hospitable，像给它一个可以留下来的空间。','a hospitable welcome；hospitable to visitors；a hospitable environment。','friendly 可只是态度友善；hospitable 常包括接待、安顿和让对方感到欢迎。',('Our neighbours were hospitable and invited us in for tea.','邻居很热情，邀请我们进去喝茶。'),('The sheltered valley offers a hospitable environment for many plants.','这个避风山谷为许多植物提供了适宜的环境。'),sources=['https://www.etymonline.com/word/hospitable','https://en.wiktionary.org/wiki/hospitable']),
E('inhospitable','英 /ˌɪnhɒsˈpɪtəbəl/；美 /ˌɪnhɑːˈspɪtəbəl/','不好客的；不宜居的；条件恶劣的','人可以不给来客好脸色，环境也可以像不肯让人待下去：严寒、干旱、没有遮蔽，都能让它 inhospitable。','借中古法语 inhospitable，接中世纪拉丁 inhospitabilis；in- 是否定。现代可理解为 in- + hospitable，但不是 in“在里面”加医院。',H+[['中世纪拉丁 in- + hospitabilis → inhospitabilis','不适合接待、不好客'],['中古法语 inhospitable → 英语 inhospitable','不好客；条件不宜停留或生存']], '写地方时通常说环境苛刻，不是在评价山川的态度；写人时才是冷淡、不欢迎客人。也可说 an inhospitable business climate，表示不利于经营的条件。','inhospitable terrain；inhospitable to visitors；an inhospitable climate。','hostile 更容易表示敌意或主动对抗；inhospitable 可以只是难以居住、缺少支持条件。',('The expedition crossed an inhospitable stretch of desert.','探险队穿过了一片环境恶劣的沙漠地带。'),('The receptionist’s cold manner made the place seem inhospitable.','前台接待员冷淡的态度让这里显得不欢迎来客。'),sources=['https://www.etymonline.com/word/inhospitable','https://en.wiktionary.org/wiki/inhospitable']),
E('hotelier','英 /həʊˈteliə/；美 /ˌhoʊtelˈjeɪ/，也可不读 /h/','酒店业主；酒店经营者','负责拥有或经营酒店的人，关注的是酒店这门生意，不是随便一位在酒店上班的员工。','借法语 hôtelier，接 hôtel 与表人的 -ier；英语是整词借入，-ier 这里不是比较级“更……”。',HAL+[['古法语 hostel / ostel → hostel(l)ier；现代法语 hôtelier','旅舍 → 经营旅舍的人'],['英语 hotelier','酒店业主或经营者']], '常见于旅游业、商业报道。可以是经营一家小旅馆的人，也可以经营多家酒店；不需要按词形理解成“更像旅馆”。','an independent hotelier；a local hotelier。','hotel manager 可是受雇管理人员；hotelier 侧重酒店经营这一职业或业主身份。',('The hotelier restored an old house and opened it to guests.','这位酒店经营者修复了一栋老房子，开始接待住客。'),('Local hoteliers discussed how to reduce food waste.','当地酒店经营者讨论了如何减少食物浪费。'),sources=['https://en.wiktionary.org/wiki/hotelier','https://www.etymonline.com/word/hotelier','https://www.merriam-webster.com/dictionary/hotelier']),
E('hospitalist','美 /ˈhɑːspɪtəlɪst/','住院医疗专职医师；专门管理住院患者照护的医师','工作重心放在患者住院的这段时间：了解病情、协调检查治疗，并衔接专科和出院安排。','hospital + -ist，现代英语职业名称。1996 年 Wachter 与 Goldman 的论文使这一称呼与现代住院医疗模式广为人知；不据此断言此前绝无这个词。',HOSP+[['英语 hospital + -ist → hospitalist','医院 + 专业人员；现代着重住院患者照护']], '不是所有在医院工作的医生都叫 hospitalist，也不表示实习阶段的住院医。它按照护场所和工作重心命名，儿科等领域也有相应 hospitalist。','a pediatric hospitalist；the hospitalist team。','resident 常说住院医师培训身份；hospitalist 说负责住院患者医疗照护的岗位，不能简单互译。',('The hospitalist explained the care plan during morning rounds.','负责住院照护的医师在晨间查房时解释了治疗计划。'),('Her family doctor spoke with the hospitalist before discharge.','出院前，她的家庭医生与负责住院照护的医师沟通过。'),sources=['https://www.merriam-webster.com/dictionary/hospitalist','https://pubmed.ncbi.nlm.nih.gov/8672160/','https://en.wiktionary.org/wiki/hospitalist']),
E('hostler','英 /ˈɒslə/，亦 /ˈhɒslə/；美 /ˈhɑːslər/，亦不读 /h/','客栈马夫；照料、调移机车的工人〔美式〕','旅人到客栈，马也要有人照料；后来铁路时代，照顾和移动车辆的工作借用了这个旧称。','古法语 hostelier / ostelier、盎格鲁法语 hostiler 接中世纪拉丁 hostilarius / hospitalarius，与 hospitale“旅舍”有关。不是 host + 随意添加的 -ler。',HAL+[['中世纪拉丁 hostilarius / hospitalarius → 古法语 hostelier、盎格鲁法语 hostiler','接待人员、旅舍管理者'],['中古英语 hostiler → hostler','旅舍人员 → 客栈照料马匹的人'],['英语 hostler〔铁路引申〕','照料、调移机车的人员']], '旧小说里的 hostler 通常在马厩照料客人的马；铁路文本里则要切换到机车。常见变体 ostler 反映 h 不发音的读法，t 通常不读。','the inn’s hostler；a locomotive hostler。','hotelier 和 hostler 远源相同，但前者如今经营酒店，后者常指旧式马夫或铁路工种。',('The hostler led the tired horses into the stable.','客栈马夫把疲惫的马牵进了马厩。'),('The railway hostler moved the locomotive into the service area.','铁路整备工把机车移进了检修区。'),sources=['https://www.etymonline.com/word/hostler','https://en.wiktionary.org/wiki/hostler']),
E('inhospitality','英 /ˌɪnhɒspɪˈtæləti/；美 /ˌɪnhɑːspɪˈtæləti/','不好客；冷淡待客；环境不宜居的性质','把“让来者待不舒服、待不下去”当作一个特点来谈：可能是人的冷淡，也可能是地方的严酷。','可按英语否定 in- + hospitality 分析；拉丁本来也有 inhospitalitas“不好客”，部分词源资料直接联系这一形式。两者共享 hospit-，不要误读为医院里的某种服务。',H+[['拉丁 hospitalitas／对应否定名词 inhospitalitas','好客／不好客'],['英语 hospitality；in- + hospitality → inhospitality〔亦有直接联系拉丁词的分析〕','待客 → 缺乏好客、不宜停留']], '这是不可数名词，inhospitality towards visitors 说对游客不欢迎。用于环境时是在拟人地说条件难以容纳生命或活动。','inhospitality towards strangers；the inhospitality of the landscape。','inhospitality 是不好客的性质；inhospitable 是描述人或环境的形容词。',('The visitors were surprised by the owner’s inhospitality.','来客对主人的冷淡感到意外。'),('The account emphasises the inhospitality of the frozen landscape.','这篇记述强调了冰封环境的严酷。'),sources=['https://en.wiktionary.org/wiki/inhospitality','https://www.collinsdictionary.com/dictionary/english/inhospitality','https://dictionary.cambridge.org/dictionary/english/inhospitality','https://www.merriam-webster.com/dictionary/inhospitality']),
]
ROOT=dict(id='C0571',meaning='客人、主人；接待、安顿来客',core='来客有地方住、有人照料：hospital、hotel、hostel 起初都接这个画面，后来分别常用于医疗、商业住宿和旅舍。',image='一位来客走进门，主人让他坐下、提供食宿；接待的场所、态度、职业与照护方式从这里分开。',intro='拉丁 hospes 既可指客人，也可指接待者，属格 hospitis 显出 hospit- 词干。更早常分析为“客人”与“主人”的复合关系。历史上的互相接待使同一词能站在关系两端，英语 host 则主要留下接待方。',forms='hospit- 在 hospital、hospitality 中较完整；经法语变化，词形可缩为 hostel、hotel 和 host。hospitality 是拉丁 hospitalitas 经法语借入，不是现代“医院”加词尾。-ist 在 hospitalist 中才是现代英语新造职业名称的词尾。',branches=[['接待与住宿场所','hospital, hotel, hostel'],['接待者、主办与相关职业','host, hostess, hosting, hotelier, hostler, hospitalist'],['人质〔更早来源有争论〕','hostage'],['对来客友好或冷淡','hospitality, hospitable, inhospitable, inhospitality'],['生命末期照护','hospice']],contrasts='host“主人”、a host of“大量”、Host“圣饼”有不同借入路线；本组只以 hospes 主人这一支为归属。hostage 的古法语来源清楚，更早有接 hoste 或拉丁 obses 的不同解释，不强画成 hospes 的确定后代。hotel 与 hostel 不是医院的缩写。hospice 可指在家提供的服务，hospitalist 也不是 resident 培训身份的同义词。',practice='把同源但不同场景的词放在一起：Our host was hospitable. We left the hostel for a nearby hotel. The hospitalist coordinated care in the hospital. 主人热情好客；旅舍和酒店提供住宿；住院医疗专职医师在医院协调照护。',words=[],exclude={})
if __name__=='__main__':
    m=json.loads((BASE/'.cache/batch200/rewrite_vid.json').read_text());r=next(r for r in m['roots'] if r['id']==ROOT['id'])
    ROOT['words']=[w for w in r['family'] if '-' not in w]
    expected=set(ROOT['words'])&set(m['owned_words']);actual={e['word'] for e in W}
    assert actual==expected,(expected-actual,actual-expected)
    assert len(W)==len(actual) and all(len(e['examples'])>=2 and len(e['history'])>=2 for e in W)
    OUT.mkdir(parents=True,exist_ok=True)
    (OUT/'roots_batch200_vid_13.json').write_text(json.dumps([ROOT],ensure_ascii=False,indent=2))
    (OUT/'words_batch200_vid_13.json').write_text(json.dumps(W,ensure_ascii=False,indent=2))
    print('hospit:',len(W),'words;',sum(len(x['examples']) for x in W),'examples')
